import { slugify, truncate } from './textutils';

function check(cond: boolean, msg: string): void {
  if (!cond) {
    throw new Error(msg);
  }
}

// slugify
check(slugify('Hello, World!') === 'hello-world', 'punctuation + spaces');
check(slugify('  Already-Clean  ') === 'already-clean', 'trim');
check(slugify('--Trim Edges!!') === 'trim-edges', 'leading AND trailing separators stripped');
check(slugify('A  B   C') === 'a-b-c', 'runs collapse to single hyphen');

// truncate
check(truncate('short', 10) === 'short', 'shorter than max unchanged');
check(truncate('exactly-ten', 11) === 'exactly-ten', 'length == max must NOT truncate');
check(truncate('this is far too long', 8) === 'this is…', 'cut with ellipsis');
check(truncate('this is far too long', 8).length === 8, 'result length is exactly max');
check(truncate('abcd', 3) === 'ab…', 'tight truncation');

console.log('PASS');

